add_action( 'woocommerce_before_single_product', 'perfectpixel_past_buyer_layout' );

function perfectpixel_past_buyer_layout() {
	global $product;
	if ( ! $product || ! is_user_logged_in() ) {
		return;
	}
	$ids = wp_parse_id_list( '{{past_buyer_product_ids}}' );
	if ( $ids && ! in_array( $product->get_id(), $ids, true ) ) {
		return;
	}
	$user = wp_get_current_user();
	if ( ! wc_customer_bought_product( $user->user_email, $user->ID, $product->get_id() ) ) {
		return;
	}
	remove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_price', 10 );
	remove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_add_to_cart', 30 );
	remove_action( 'woocommerce_before_single_product_summary', 'woocommerce_show_product_sale_flash', 10 );
	add_action( 'woocommerce_single_product_summary', 'perfectpixel_past_buyer_message', 30 );
}

function perfectpixel_past_buyer_message() {
	echo '<div class="woocommerce-info perfectpixel-past-buyer">' . wp_kses_post( '{{past_buyer_message}}' ) . '</div>';
}
